<script setup lang="ts">
import { computed, ref } from 'vue'
import { useWorkspaceStore } from '../stores/workspace'
import ReplayChart from '../components/ReplayChart.vue'
import { number, reasonName, time } from '../components/format'
const store = useWorkspaceStore()
const start = ref(store.query.start ?? ''), end = ref(store.query.end ?? ''), budget = ref(300), featureFilter = ref(''), featurePage = ref(1)
const pageSize = ref(store.query.page_size ?? 100)
const missed = computed(() => store.evaluation?.intervals.filter(x => x.kind === 'missed_attack') ?? [])
const falsePositives = computed(() => store.evaluation?.intervals.filter(x => x.kind === 'false_positive') ?? [])
const features = computed(() => (store.minute?.feature_names.map((name, i) => ({ name, i })) ?? []).filter(x => x.name.includes(featureFilter.value)))
const featureRows = computed(() => features.value.slice((featurePage.value - 1) * 20, featurePage.value * 20))
const apply = () => { store.query = { page: 1, page_size: pageSize.value, start: start.value || undefined, end: end.value || undefined }; store.alarmPage = 1; void store.loadResults() }
const page = (delta: number) => { store.query.page = (store.query.page ?? 1) + delta; void store.loadResults() }
const alarmPage = (delta: number) => { store.alarmPage += delta; void store.loadResults() }
defineEmits<{ navigate: [page: 'tasks'] }>()
</script>
<template>
  <div class="section-heading"><div><span class="eyebrow">MINUTE REPLAY</span><h2>回到异常发生的那一分钟</h2><p>曲线按 UTC 对齐，报警与漏报都能独立查找。</p></div><button v-if="store.mode === 'mock'" class="secondary" @click="store.openRun('synthetic-succeeded')">载入统一合成样例 ↗</button></div>
  <div v-if="!store.activeRun || store.activeRun.status !== 'succeeded'" class="panel empty"><div class="empty-symbol">⌁</div><h3>还没有可查看的结果</h3><p>请先完成检测任务，或载入合成样例。</p><button @click="$emit('navigate', 'tasks')">进入检测任务 →</button></div>
  <template v-else>
    <article class="panel"><form class="range-form" @submit.prevent="apply"><label>起点 UTC（包含）<input v-model="start" placeholder="2026-01-01T00:00:00Z" aria-label="起点 UTC"></label><label>终点 UTC（不包含）<input v-model="end" placeholder="2026-01-01T00:04:00Z" aria-label="终点 UTC"></label><label class="small-control">每页分钟<select v-model="pageSize"><option :value="100">100</option><option :value="500">500</option><option :value="1000">1000</option></select></label><button :disabled="store.loading">应用范围</button></form><p class="hint">时间筛选仅影响曲线和列表。评价始终读取任务的完整结果；不会在页面重算。</p></article>
    <div v-if="store.loading" class="loading" role="status">正在读取结果…</div>
    <article class="panel chart-panel"><div class="panel-heading"><div><h3>流量与异常分数</h3><p class="hint">{{ store.series?.total ?? '—' }} 条范围内记录 · 第 {{ store.series?.page ?? 1 }} 页 · 缺失值保留断点</p></div><label class="sample-control">图表密度<select v-model="budget"><option :value="300">标准</option><option :value="1000">详细</option></select></label></div><ReplayChart v-if="store.series?.items.length" :points="store.series.items" :budget="budget" @select="store.selectMinute"/><div v-else class="empty">当前范围没有分钟记录</div><p class="hint">密度只控制当前页绘图；保留报警和无效分钟。点击数据点查看特征，表格可逐分钟查询。</p>
    <div class="table-scroll"><table><thead><tr><th>分钟 · UTC</th><th>流记录数</th><th>异常分数</th><th>阈值</th><th>检测状态</th><th>查看</th></tr></thead><tbody><tr v-for="point in store.series?.items" :key="point.timestamp"><td class="mono">{{ time(point.timestamp) }}</td><td>{{ number(point.flow_count) }}</td><td>{{ number(point.score) }}</td><td>{{ number(point.threshold) }}</td><td><span class="badge" :class="!point.valid ? 'queued' : point.alarm ? 'failed' : 'succeeded'">{{ !point.valid ? reasonName[point.invalid_reason ?? ''] : point.alarm ? '报警' : '未报警' }}</span></td><td><button class="text-button" @click="store.selectMinute(point.timestamp)">详情 ↗</button></td></tr></tbody></table></div><div class="pagination"><button class="secondary" :disabled="store.loading || (store.series?.page ?? 1) <= 1" @click="page(-1)">上一页</button><span>当前页 {{ store.series?.items.length ?? 0 }} 条 / 范围内 {{ store.series?.total ?? 0 }} 条</span><button class="secondary" :disabled="store.loading || !store.series || store.series.page * store.series.page_size >= store.series.total" @click="page(1)">下一页</button></div></article>
    <div class="analysis-grid"><article class="panel"><div class="panel-heading"><h3><span class="dot coral"></span>报警记录</h3><span class="count">{{ store.alarms?.total ?? '—' }}</span></div><div v-if="!store.alarms?.items.length" class="empty compact">没有报警记录</div><button v-for="point in store.alarms?.items" class="interval-row" @click="store.selectMinute(point.timestamp)"><span>{{ time(point.timestamp) }}<small>分数 {{ number(point.score) }} · 阈值 {{ number(point.threshold) }}</small></span><span>↗</span></button><div class="pagination"><button class="text-button" :disabled="store.alarmPage <= 1 || store.loading" @click="alarmPage(-1)">上一页</button><span>第 {{ store.alarmPage }} 页</span><button class="text-button" :disabled="store.loading || !store.alarms || store.alarms.page * store.alarms.page_size >= store.alarms.total" @click="alarmPage(1)">下一页</button></div></article>
    <article class="panel missed-panel"><div class="panel-heading"><h3><span class="dot gold"></span>完全漏报片段</h3><span class="tag">独立标签 · 事后核查</span></div><p class="hint">直接来自任务评价，不依赖报警列表；范围使用 [起点，终点)。</p><div v-if="!missed.length" class="empty compact">{{ store.evaluation?.available ? '评价未列出完全漏报片段' : '标签缺失，无法核查漏报' }}</div><button v-for="interval in missed" data-test="missed-attack" class="interval-row" @click="store.selectMinute(interval.start)"><span>{{ time(interval.start) }}<small>至 {{ time(interval.end) }} · {{ interval.minute_count }} 分钟</small></span><span>定位 ↗</span></button><details v-if="falsePositives.length"><summary>误报片段 · {{ falsePositives.length }}</summary><button v-for="interval in falsePositives" class="interval-row" @click="store.selectMinute(interval.start)"><span>{{ time(interval.start) }}<small>{{ interval.minute_count }} 分钟</small></span>↗</button></details></article></div>
    <article class="panel"><div class="panel-heading"><div><h3>分钟特征与解释通道</h3><p class="hint">{{ store.minute ? time(store.minute.point.timestamp) : '选择曲线、分钟记录或评价片段查看' }}</p></div><span v-if="store.minute?.labels" class="tag">事后标签 {{ Object.entries(store.minute.labels).filter(([, value]) => value > 0).map(([name]) => name).join(' / ') || '八标签均零 · 正常候选' }}</span></div><template v-if="store.minute"><div class="channel-legend"><span>当前特征 <small>原始计数</small></span><span>历史偏离 <small>相对历史的带符号偏离</small></span><span>重构误差 <small>当前 / 历史输入的逐字段平方误差</small></span></div><p class="hint">通道仅提供排查线索，不代表攻击归因。隔离森林不提供重构误差；缺通道显示“未提供”。</p><label class="feature-search">查找特征<input v-model="featureFilter" placeholder="输入字段名称" @input="featurePage = 1"></label><div class="table-scroll"><table class="feature-table"><thead><tr><th>字段</th><th>当前特征</th><th>历史偏离</th><th>重构误差 · 当前</th><th>重构误差 · 历史</th></tr></thead><tbody><tr v-for="f in featureRows" :key="f.i"><td class="feature-name">{{ f.name }}</td><td>{{ number(store.minute.current?.[f.i]) }}</td><td>{{ number(store.minute.history_residual?.[f.i]) }}</td><td>{{ number(store.minute.reconstruction_error_current?.[f.i]) }}</td><td>{{ number(store.minute.reconstruction_error_history?.[f.i]) }}</td></tr></tbody></table></div><div class="pagination"><button class="text-button" :disabled="featurePage <= 1" @click="featurePage--">上一页</button><span>{{ features.length }} 个字段 · 每页 20 个</span><button class="text-button" :disabled="featurePage * 20 >= features.length" @click="featurePage++">下一页</button></div></template><div v-else class="empty compact">尚未选择分钟</div></article>
  </template>
</template>
